on-error.log-to-eventhub:
@{
      var body = new JObject(
        new JProperty("ts", DateTime.UtcNow.ToString("o")),
        new JProperty("apiId",         context.Api.Id),
        new JProperty("operationName", context.Operation?.Name ?? ""),
        new JProperty("requestId",     context.RequestId.ToString()),
        new JProperty("correlationId", context.Variables.GetValueOrDefault("cid", "")),
        new JProperty("traceparent",   context.Request.Headers.GetValueOrDefault("traceparent","")),
        new JProperty("status",        context.Response?.StatusCode ?? 0),
        new JProperty("errorReason",   context.LastError?.Reason ?? ""),
        new JProperty("errorMessage",  context.LastError?.Message ?? ""),
        new JProperty("totalTimeMs",   (DateTime.UtcNow - context.Timestamp).TotalMilliseconds)
      );
      return body.ToString(Newtonsoft.Json.Formatting.None);
    }
